namespace InventoryService.Domain;


/// Inventory record for a single product. One row per product that this service stocks.


/// Only quantities live here. The product's name, price, images and category stay in the
/// Laravel application, which owns the catalogue; duplicating them would create two sources
/// of truth for data this service never reads.

public class InventoryItem
{

    /// The product's primary key in the Laravel application, used directly as our own key.
    /// Never generated by this database.

    public long ProductId { get; set; }

    /// Physical stock. Changed by restocking, not by reservations.
    public int QuantityOnHand { get; set; }

    /// Quantity held by reservations in the ReservationStatus.Active state.
    public int QuantityReserved { get; set; }


    /// What <c>GetStock</c> reports: the quantity that can still be reserved. Computed, never
    /// stored, so it cannot drift away from the two columns it derives from.

    public int AvailableQuantity => QuantityOnHand - QuantityReserved;
}
